from typing import List
import math

class Solution:
    def findValidSplit(self, nums: List[int]) -> int:
        def prime_factors(n):
            i = 2
            factors = set()
            while i * i <= n:
                if n % i:
                    i += 1
                else:
                    n //= i
                    factors.add(i)
            if n > 1:
                factors.add(n)
            return factors

        n = len(nums)
        right_factors = {}
        for num in nums:
            for factor in prime_factors(num):
                right_factors[factor] = right_factors.get(factor, 0) + 1

        left_factors = set()
        for i in range(n - 1):
            for factor in prime_factors(nums[i]):
                left_factors.add(factor)
                right_factors[factor] -= 1
                if right_factors[factor] == 0:
                    del right_factors[factor]
            if not right_factors:
                return i

        return -1

from collections import defaultdict

class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        # Create an adjacency list representation of the network
        adj_list = defaultdict(list)
        for u, v in connections:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Initialize the lowest cost array and visited array
        low_cost = [float('inf')] * n
        visited = [False] * n
        result = []

        # Helper function to perform DFS
        def dfs(node):
            nonlocal low_cost, visited, result
            low_cost[node] = 0
            visited[node] = True
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
                    low_cost[node] = min(low_cost[node], low_cost[neighbor])
                    if low_cost[neighbor] < low_cost[node]:
                        result.append([node, neighbor])

        # Start DFS from each node
        for i in range(n):
            if not visited[i]:
                dfs(i)

        return result

from typing import List

class Solution:
    def findDifferentBinaryString(self, nums: List[str]) -> str:
        n = len(nums)
        num_set = set(nums)

        for i in range(1 << n):
            candidate = bin(i)[2:].zfill(n)
            if candidate not in num_set:
                return candidate

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        max_avg = float('-inf')
        window_sum = sum(nums[:k])
        for i in range(k, len(nums)):
            window_sum += nums[i] - nums[i-k]
            if window_sum > max_avg:
                max_avg = window_sum
        return max_avg / k

class Solution:
    def numPoints(self, darts: List[List[int]], r: int) -> int:
        max_count = 0

        for x, y in darts:
            count = 0
            for dx, dy in darts:
                if (x - dx)**2 + (y - dy)**2 <= r**2:
                    count += 1
            max_count = max(max_count, count)

        return max_count

