class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            return TreeNode(val, left=root)

        queue = deque([(root, 1)])

        while queue:
            node, current_depth = queue.popleft()

            if current_depth == depth - 1:
                node.left = TreeNode(val, left=node.left)
                node.right = TreeNode(val, right=node.right)
            elif current_depth < depth - 1:
                if node.left:
                    queue.append((node.left, current_depth + 1))
                if node.right:
                    queue.append((node.right, current_depth + 1))

        return root

class Solution:
    def checkPartitioning(self, s: str) -> bool:
        n = len(s)

        # Helper function to check if a substring is a palindrome
        def is_palindrome(i, j):
            while i < j:
                if s[i] != s[j]:
                    return False
                i += 1
                j -= 1
            return True

        # Check for the first partition
        for i in range(1, n-1):
            if not is_palindrome(0, i):
                continue

            # Check for the second partition
            for j in range(i+1, n):
                if is_palindrome(i, j-1) and is_palindrome(j, n-1):
                    return True

        return False

class Solution:
    def specialArray(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        left, right = 0, n

        while left < right:
            mid = (left + right) // 2
            count = n - bisect_left(nums, mid)

            if count == mid:
                return mid
            elif count > mid:
                left = mid + 1
            else:
                right = mid

        return -1

class Solution:
    def buddyStrings(self, s: str, goal: str) -> bool:
        # Check if the lengths of the strings are different
        if len(s) != len(goal):
            return False

        # Count the frequency of each character in both strings
        freq_s = {}
        freq_goal = {}

        for char in s:
            freq_s[char] = freq_s.get(char, 0) + 1

        for char in goal:
            freq_goal[char] = freq_goal.get(char, 0) + 1

        # Check if the frequency of any character is not equal
        if len(freq_s) != len(freq_goal):
            return False

        # Count the number of characters that appear exactly twice in both strings
        count_double = sum(1 for char, freq in freq_s.items() if freq == 2)

        # If there are more than two characters that appear exactly twice, return False
        if count_double > 2:
            return False

        # Check if the frequency of any character appears exactly once in both strings
        for char, freq in freq_s.items():
            if freq == 1:
                return True

        return False

class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        nums.sort()
        left = 0
        total = 0
        result = 0

        for right in range(len(nums)):
            total += nums[right]

            while (right - left + 1) * nums[right] - total > k:
                total -= nums[left]
                left += 1

            result = max(result, right - left + 1)

        return result

from typing import List

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        def hash_word(word):
            return sum(1 << (ord(c) - ord('a')) for c in word)

        word_set = set(hash_word(word) for word in words)
        visited = set()
        max_group_size = 0
        num_groups = 0

        for word_hash in word_set:
            if word_hash in visited:
                continue

            stack = [word_hash]
            group_size = 0

            while stack:
                current_hash = stack.pop()
                if current_hash in visited:
                    continue
                visited.add(current_hash)
                group_size += 1

                # Check by removing one character
                for i in range(26):
                    if current_hash & (1 << i):
                        new_hash = current_hash ^ (1 << i)
                        if new_hash in word_set:
                            stack.append(new_hash)

                # Check by adding one character
                for i in range(26):
                    if not current_hash & (1 << i):
                        new_hash = current_hash | (1 << i)
                        if new_hash in word_set:
                            stack.append(new_hash)

                # Check by replacing one character
                for i in range(26):
                    if current_hash & (1 << i):
                        for j in range(26):
                            if not current_hash & (1 << j):
                                new_hash = (current_hash ^ (1 << i)) | (1 << j)
                                if new_hash in word_set:
                                    stack.append(new_hash)

            max_group_size = max(max_group_size, group_size)
            num_groups += 1

        return [num_groups, max_group_size]

