class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        mapping_dict = {ord(old): set() for old, _ in mappings}
        for old, new in mappings:
            mapping_dict[ord(old)].add(ord(new))

        sub_len = len(sub)
        for i in range(len(s) - sub_len + 1):
            if self.can_form_substring(s[i:i + sub_len], sub, mapping_dict):
                return True
        return False

    def can_form_substring(self, s_part: str, sub: str, mapping_dict: dict) -> bool:
        for c1, c2 in zip(s_part, sub):
            if ord(c1) != ord(c2) and ord(c2) not in mapping_dict.get(ord(c1), set()):
                return False
        return True

