class Solution:
    def shareCandies(self, candies: List[int], k: int) -> int:
        count = Counter(candies)
        if len(count) == 0:
            return 0

        start = 0
        max_count = float('-inf')
        for end in range(len(candies)):
            count[candies[end]] += 1
            while end - start + 1 > k:
                count[candies[start]] -= 1
                if count[candies[start]] == 0:
                    del count[candies[start]]
                start += 1

            max_count = max(max_count, len(count))

        return max_count

class Solution:
    def earliestAcq(self, logs: List[List[int]], n: int) -> int:
        # Initialize the parent array for Union-Find
        parent = list(range(n))

        # Function to find the root of a node using path compression
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        # Function to union two sets
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        # Sort the logs by timestamp
        logs.sort()

        # Count the number of connected components
        count = n
        for timestamp, x, y in logs:
            union(x, y)
            if find(x) == find(y):
                count -= 1
            if count == 1:
                return timestamp

        return -1

