class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        # Helper function to check if two trees have the same leaf value sequence
        def compare_trees(root1, root2):
            # Base case: if both nodes are None, they are leaf nodes
            if not root1 and not root2:
                return True
            # If one node is None, the other must be leaf
            if not root1 or not root2:
                return False
            # Check if the current nodes have the same leaf value
            return root1.val == root2.val and compare_trees(root1.left, root2.left) and compare_trees(root1.right, root2.right)

        # Compare the two trees
        return compare_trees(root1, root2)

class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(n):
            # Check for odd length palindromes centered at i
            l, r = i, i
            while l >= 0 and r < n and s[l] == s[r]:
                if r - l + 1 >= k:
                    dp[r + 1] = max(dp[r + 1], dp[l] + 1)
                l -= 1
                r += 1

            # Check for even length palindromes centered between i and i+1
            l, r = i, i + 1
            while l >= 0 and r < n and s[l] == s[r]:
                if r - l + 1 >= k:
                    dp[r + 1] = max(dp[r + 1], dp[l] + 1)
                l -= 1
                r += 1

        return dp[n]

class Solution:
    def splitArray(self, nums: List[int]) -> bool:
        n = len(nums)
        prefix_sums = [0] * (n + 1)

        # Calculate prefix sums
        for i in range(1, n + 1):
            prefix_sums[i] = prefix_sums[i - 1] + nums[i - 1]

        # Iterate over possible values of j
        for j in range(2, n - 2):
            left_sum = prefix_sums[j - 1]
            right_sum = prefix_sums[n] - prefix_sums[j + 1]

            # Check if the sum of the two halves equals the left and right sums
            if left_sum == right_sum:
                continue

            # Check if we can split the array into four parts
            for i in range(1, j - 1):
                left_left_sum = prefix_sums[i - 1]
                left_right_sum = prefix_sums[j - 1] - prefix_sums[i]

                if left_left_sum == left_right_sum:
                    for k in range(j + 2, n):
                        right_left_sum = prefix_sums[k - 1] - prefix_sums[j + 1]
                        right_right_sum = prefix_sums[n] - prefix_sums[k]

                        if right_left_sum == right_right_sum:
                            return True

        return False

class Solution:
    def addOperators(self, num: str, target: int) -> List[str]:
        if not num:
            return []

        result = []
        self.dfs(num, target, 0, 0, "", result)
        return result

    def dfs(self, num: str, target: int, index: int, prev: int, curr: str, result: List[str]):
        if index == len(num):
            if prev == target:
                result.append(curr)
            return

        for i in range(index, len(num)):
            if i > index and num[index] == '0':
                break

            n = int(num[index:i + 1])
            if index == 0:
                self.dfs(num, target, i + 1, n, str(n), result)
            else:
                self.dfs(num, target, i + 1, prev + n, curr + '+' + str(n), result)
                self.dfs(num, target, i + 1, prev - n, curr + '-' + str(n), result)
                self.dfs(num, target, i + 1, prev * n, curr + '*' + str(n), result)

