class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        counter = Counter()
        for x, y in coordinates:
            counter[x ^ y] += 1

        result = 0
        for x, y in coordinates:
            if x + k in counter:
                result += counter[x + k]

        return result

