from collections import deque

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        rows, cols = len(forest), len(forest[0])

        # Find all trees
        trees = []
        for i in range(rows):
            for j in range(cols):
                if forest[i][j] > 1:
                    trees.append((forest[i][j], i, j))

        # Sort trees by height
        trees.sort()

        queue = deque([(0, 0)])
        visited = set()
        steps = 0

        while queue:
            size = len(queue)

            for _ in range(size):
                r, c = queue.popleft()

                if (r, c) in visited:
                    continue

                visited.add((r, c))

                if r == rows - 1 and c == cols - 1:
                    return steps

                # Explore neighbors
                for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < rows and 0 <= nc < cols and forest[nr][nc] != 0:
                        forest[nr][nc] = 1
                        queue.append((nr, nc))

            steps += 1

        return -1

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        if not obstacleGrid or not obstacleGrid[0]:
            return 0

        rows, cols = len(obstacleGrid), len(obstacleGrid[0])
        dp = [[0] * cols for _ in range(rows)]

        # Initialize the first row
        for i in range(cols):
            if obstacleGrid[0][i] == 1:
                dp[0][i] = 0
            else:
                dp[0][i] = 1

        # Initialize the first column
        for j in range(rows):
            if obstacleGrid[j][0] == 1:
                dp[j][0] = 0
            else:
                dp[j][0] = 1

        # Fill the dp table
        for i in range(1, rows):
            for j in range(1, cols):
                if obstacleGrid[i][j] == 1:
                    dp[i][j] = 0
                else:
                    dp[i][j] = dp[i-1][j] + dp[i][j-1]

        return dp[-1][-1]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            new_root = TreeNode(val)
            new_root.left = root
            return new_root

        queue = deque([root])
        current_depth = 1

        while queue:
            if current_depth == depth - 1:
                for _ in range(len(queue)):
                    node = queue.popleft()
                    new_left = TreeNode(val)
                    new_right = TreeNode(val)
                    new_left.left = node.left
                    new_right.right = node.right
                    node.left = new_left
                    node.right = new_right
            else:
                for _ in range(len(queue)):
                    node = queue.popleft()
                    if node.left:
                        queue.append(node.left)
                    if node.right:
                        queue.append(node.right)
            current_depth += 1

        return root

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs)
        m = len(strs[0])
        delete_count = 0
        keep = [True] * m

        for j in range(m):
            for i in range(1, n):
                if keep[j] and strs[i][j] < strs[i-1][j]:
                    delete_count += 1
                    keep[j] = False
                    break

        return delete_count

class Solution:
    def findUnsortedSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        left = right = -1
        min_val = max_val = nums[0]

        # Find the maximum index where the array is not in increasing order
        for i in range(1, n):
            if nums[i] < max_val:
                right = i
            else:
                max_val = nums[i]

        # Find the minimum index where the array is not in decreasing order
        for i in range(n-2, -1, -1):
            if nums[i] > min_val:
                left = i
            else:
                min_val = nums[i]

        # If no unsorted subarray is found, return 0
        if left == -1:
            return 0

        # Return the length of the unsorted subarray
        return right - left + 1

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        m, n = len(land), len(land[0])
        result = []

        for i in range(m):
            for j in range(n):
                if land[i][j] == 1:
                    # Start of a new farmland group
                    start_row, start_col = i, j
                    # Find the bottom right corner of this group
                    end_row, end_col = i, j
                    while end_row < m - 1 and land[end_row + 1][end_col] == 1:
                        end_row += 1
                    while end_col < n - 1 and land[end_row][end_col + 1] == 1:
                        end_col += 1

                    # Mark the entire group as visited
                    for x in range(start_row, end_row + 1):
                        for y in range(start_col, end_col + 1):
                            land[x][y] = 0

                    # Add the group to the result
                    result.append([start_row, start_col, end_row, end_col])

        return result

class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        stack = []
        for node in preorder.split(','):
            if not stack:
                if node != "#":
                    return False
                else:
                    stack.append(node)
            else:
                if node == "#":
                    while stack and stack[-1] == "#":
                        stack.pop()
                        if not stack:
                            return False
                    stack.pop()
                else:
                    stack.append(node)
        return len(stack) == 1 and stack[0] == "#"

