class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        n = len(positions)
        if n == 1:
            return 0

        def distance(x, y):
            return sum(math.sqrt((x - px)**2 + (y - py)**2) for px, py in positions)

        x_min, x_max = min(pos[0] for pos in positions), max(pos[0] for pos in positions)
        y_min, y_max = min(pos[1] for pos in positions), max(pos[1] for pos in positions)

        step = 100
        while step > 1e-6:
            best_dist = float('inf')
            best_x, best_y = None, None

            for dx in [-step, 0, step]:
                for dy in [-step, 0, step]:
                    x, y = x_min + (x_max - x_min) * 0.5 + dx, y_min + (y_max - y_min) * 0.5 + dy
                    dist = distance(x, y)
                    if dist < best_dist:
                        best_dist = dist
                        best_x, best_y = x, y

            x_min, x_max = best_x - step, best_x + step
            y_min, y_max = best_y - step, best_y + step
            step /= 10

        return best_dist

class Solution:
    def shareCandies(self, candies: List[int], k: int) -> int:
        from collections import Counter

        # Count the frequency of each candy flavor
        candy_count = Counter(candies)
        unique_flavors = len(candy_count)

        # If k is 0, we don't need to share any candies
        if k == 0:
            return unique_flavors

        # Initialize the result with the total number of unique flavors
        max_unique_flavors = unique_flavors

        # Use a sliding window to find the minimum number of unique flavors when sharing k candies
        for i in range(k):
            candy_count[candies[i]] -= 1
            if candy_count[candies[i]] == 0:
                unique_flavors -= 1

        max_unique_flavors = min(max_unique_flavors, unique_flavors)

        for i in range(k, len(candies)):
            candy_count[candies[i-k]] += 1
            if candy_count[candies[i-k]] == 1:
                unique_flavors += 1

            candy_count[candies[i]] -= 1
            if candy_count[candies[i]] == 0:
                unique_flavors -= 1

            max_unique_flavors = min(max_unique_flavors, unique_flavors)

        return max_unique_flavors

class Solution:
    def isCovered(self, ranges: List[List[int]], left: int, right: int) -> bool:
        covered = set()

        for start, end in ranges:
            covered.update(range(start, end + 1))

        return all(left <= num <= right for num in range(left, right + 1) if num in covered)

class Solution:
    def minMovesToMakePalindrome(self, s: str) -> int:
        def helper(s):
            if len(s) <= 2:
                return 0
            for i in range(len(s)):
                if s[i] == s[-1]:
                    return i + helper(s[:i] + s[i+1:-1])
            return float('inf')

        return helper(list(s))

