class Solution:
    def cellsInRange(self, s: str) -> List[str]:
        start_col, start_row = s[0], int(s[1])
        end_col, end_row = s[3], int(s[4])
        result = []

        for col in range(ord(start_col), ord(end_col) + 1):
            for row in range(start_row, end_row + 1):
                result.append(f"{chr(col)}{row}")

        return result

from typing import *
import collections

class Solution:
    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        n = len(edges)
        dist1 = [-1] * n
        dist2 = [-1] * n

        q1 = collections.deque([node1])
        q2 = collections.deque([node2])

        while q1:
            u = q1.popleft()
            if dist1[u] == -1:
                dist1[u] = dist1[node1] + 1
                q1.append(edges[u])

        while q2:
            u = q2.popleft()
            if dist2[u] == -1:
                dist2[u] = dist2[node2] + 1
                q2.append(edges[u])

        min_dist = float('inf')
        res = -1

        for i in range(n):
            if dist1[i] != -1 and dist2[i] != -1 and max(dist1[i], dist2[i]) < min_dist:
                min_dist = max(dist1[i], dist2[i])
                res = i

        return res

