class Solution:
    def minOperations(self, nums: List[int], x: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        # Initialize variables to store the result
        left, right, total = 0, n, 0

        # Iterate through the prefix sum array
        while left <= right:
            mid = (left + right) // 2
            if prefix_sum[mid] > x:
                right = mid - 1
            elif prefix_sum[mid] < x:
                left = mid + 1
            else:
                # Calculate the number of operations needed
                operations = mid
                total -= prefix_sum[mid]
                # Adjust the range based on whether we can reduce x with the current element
                if total < 0:
                    right -= 1
                else:
                    left += 1
                break

        return operations

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False

        shifts = [0] * 26
        for i in range(len(s)):
            diff = (ord(t[i]) - ord(s[i])) % 26
            if diff == 0:
                continue
            if shifts[diff] >= 26:
                return False
            shifts[diff] += 1

        return True

class Solution:
    def sumScores(self, s: str) -> int:
        n = len(s)
        result = n
        for i in range(1, n):
            if s.startswith(s[i:], 0, n - i):
                result += n - i
        return result

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        m, n = len(land), len(land[0])
        ans = []

        def dfs(r, c):
            if r < 0 or r >= m or c < 0 or c >= n or land[r][c] == 0:
                return
            land[r][c] = 0  # Mark as visited
            nonlocal max_r, max_c
            max_r, max_c = max(max_r, r), max(max_c, c)
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)

        for i in range(m):
            for j in range(n):
                if land[i][j] == 1:
                    max_r, max_c = i, j
                    dfs(i, j)
                    ans.append([i, j, max_r, max_c])

        return ans

