class Solution:
    def splitArray(self, nums: List[int]) -> bool:
        n = len(nums)
        if n < 7:
            return False

        # Calculate prefix sums
        prefix_sum = [0] * n
        prefix_sum[0] = nums[0]
        for i in range(1, n):
            prefix_sum[i] = prefix_sum[i - 1] + nums[i]

        # Find all possible sums for subarray (0, i-1)
        seen_sums = {}
        for i in range(3, n - 3):
            for j in range(1, i - 1):
                if prefix_sum[j - 1] == prefix_sum[i - 1] - prefix_sum[j]:
                    target = prefix_sum[j - 1]
                    if target not in seen_sums:
                        seen_sums[target] = []
                    seen_sums[target].append(j)

        # Check for valid k for each target sum
        for k in range(n - 2, 5, -1):
            for j in range(k - 2, 3, -1):
                if prefix_sum[k - 1] - prefix_sum[j] == prefix_sum[n - 1] - prefix_sum[k]:
                    target = prefix_sum[k - 1] - prefix_sum[j]
                    if target in seen_sums:
                        for i in seen_sums[target]:
                            if i < j - 1:
                                return True

        return False

class Solution:
    def maximumAlternatingSubarraySum(self, nums: List[int]) -> int:
        max_sum = float('-inf')
        current_sum = nums[0]
        for i in range(1, len(nums)):
            if (i % 2 == 0):
                current_sum += nums[i]
            else:
                current_sum -= nums[i]
            max_sum = max(max_sum, current_sum)
            if current_sum < 0:
                current_sum = nums[i]
        return max_sum

