class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        if not strs or not strs[0]:
            return 0

        n, m = len(strs), len(strs[0])
        deleted = [False] * m
        deletions = 0

        for j in range(m):
            for i in range(1, n):
                if not deleted[j] and strs[i][j] < strs[i - 1][j]:
                    deletions += 1
                    deleted[j] = True
                    break

        return deletions

class Solution:
    def minKBitFlips(self, nums: List[int], k: int) -> int:
        n = len(nums)
        flips = 0
        flip_count = 0

        for i in range(n):
            # Check if we need to flip at position i
            if (flip_count % 2 == nums[i]):
                # If we need to flip, check if there are enough elements to flip
                if (i + k > n):
                    return -1
                # Flip the current element and the next k-1 elements
                for j in range(i, i + k):
                    nums[j] ^= 1
                flip_count += 1
                flips += 1

        return flips

class Solution:
    def minMoves(self, nums: List[int], limit: int) -> int:
        n = len(nums)
        moves = 0

        # Iterate through the array from the start
        for i in range(n):
            # Calculate the difference between the current element and the next element
            diff = nums[i] + nums[(n - 1 - i) % n]

            # If the difference is greater than the limit, increment the moves counter
            if diff > limit:
                moves += 1

        return moves

class Solution:
    def buddyStrings(self, s: str, goal: str) -> bool:
        if len(s) != len(goal):
            return False

        if s == goal:
            # Check if there's any duplicate character in s
            return len(set(s)) < len(s)

        # Find the indices where s and goal differ
        diff = [(i, j) for i, j in zip(s, goal) if i != j]

        # There must be exactly two differences and they must be swappable
        return len(diff) == 2 and s[diff[0][0]] == goal[diff[1][0]] and s[diff[0][1]] == goal[diff[1][1]]

class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        n = len(hamsters)
        buckets = 0
        i = 0

        while i < n:
            if hamsters[i] == 'H':
                # Check if we can place a bucket to the right
                if i + 1 < n and hamsters[i + 1] == '.':
                    buckets += 1
                    i += 2  # Skip the next cell as it's covered by the current bucket
                # Check if we can place a bucket to the left
                elif i - 1 >= 0 and hamsters[i - 1] == '.':
                    buckets += 1
                    i += 1  # Move to the next cell
                else:
                    return -1  # No way to place a bucket to feed this hamster
            else:
                i += 1  # Move to the next cell

        return buckets

class Solution:
    def closedIsland(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        rows, cols = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

        def dfs(i, j):
            if i < 0 or i >= rows or j < 0 or j >= cols or grid[i][j] == 1:
                return True

            grid[i][j] = 1  # Mark as visited
            for dx, dy in directions:
                x, y = i + dx, j + dy
                if not dfs(x, y):
                    return False
            return True

        count = 0
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 0 and dfs(i, j):
                    count += 1

        return count

class Solution:
    def clearDigits(self, s: str) -> str:
        result = []
        digit_indices = []

        # Collect indices of all digits
        for i, char in enumerate(s):
            if char.isdigit():
                digit_indices.append(i)

        # Iterate over the string and build the result
        for i, char in enumerate(s):
            if i not in digit_indices:
                # Check if there's a digit to the right of this character
                remove = False
                for digit_index in digit_indices:
                    if i < digit_index:
                        remove = True
                        break
                if not remove:
                    result.append(char)

        return ''.join(result)

