class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        n = len(hamsters)
        count = 0
        for i in range(n):
            if hamsters[i] == 'H':
                # Check if the next character is also H
                if i < n-1 and hamsters[i+1] == 'H':
                    return -1
                # Check if the previous character is not H
                elif i > 0 and hamsters[i-1] != 'H':
                    count += 1
                # Update the position of the current character
                i += 1

        return count

from collections import defaultdict

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        # Create a dictionary to store the neighbors of each node
        neighbors = defaultdict(list)
        for i in range(len(graph)):
            for j in range(len(graph[0])):
                if graph[i][j] == 1:
                    neighbors[i].append(j)
                    neighbors[j].append(i)

        # Calculate the number of infected nodes in each component of the graph
        infected_count = {node: sum(1 for neighbor in neighbors[node] if neighbor in initial) for node in range(len(graph))}

        # Calculate the minimum number of infected nodes when a node is removed
        min_infected = float('inf')
        best_node = -1

        for node in initial:
            # Remove the current node and calculate the new number of infected nodes
            new_infected = len(initial) - sum(1 for neighbor in neighbors[node] if neighbor in initial)

            # Update the minimum number of infected nodes and the best node
            if new_infected < min_infected:
                min_infected = new_infected
                best_node = node

        return best_node

