        return max(max_val - min_val, len(arrays) * 2)

from collections import defaultdict

class Solution:
    def findPattern(self, board: List[List[int]], pattern: List[str]) -> List[int]:
        m, n = len(board), len(board[0])
        mp = defaultdict(list)
        for i in range(m):
            for j in range(n):
                if board[i][j] > 0:
                    mp[board[i][j]].append((i, j))

        def dfs(i, j, path):
            if len(path) == len(pattern):
                return True
            if i >= m or j >= n or pattern[len(path)] not in mp or board[i][j] not in mp[pattern[len(path)]]:
                return False

            for ni, nj in mp[pattern[len(path)]]:
                if ni == i + 1 and nj == j and (ni, nj) not in path:
                    continue
                if ni == i and nj == j + 1 and (ni, nj) not in path:
                    continue
                if ni == i + 1 and nj == j + 1 and (ni, nj) not in path:
                    continue

                board[i][j], board[ni][nj] = board[ni][nj], board[i][j]
                path.append((ni, nj))
                if dfs(ni, nj, path):
                    return True
                path.pop()
                board[i][j], board[ni][nj] = board[ni][nj], board[i][j]

            return False

        for i in range(m):
            for j in range(n):
                if board[i][j] > 0:
                    for ni, nj in mp[pattern[0]]:
                        if ni == i and nj == j and (ni, nj) not in [(i, j)]:
                            continue
                        if ni == i and nj == j + 1 and (ni, nj) not in [(i, j)]:
                            continue
                        if ni == i + 1 and nj == j + 1 and (ni, nj) not in [(i, j)]:
                            continue

                        board[i][j], board[ni][nj] = board[ni][nj], board[i][j]
                        if dfs(ni, nj, [(ni, nj)]):
                            return [i, j]
                        board[i][j], board[ni][nj] = board[ni][nj], board[i][j]

        return [-1, -1]

