import collections

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        # Sort each word based on its characters
        sorted_words = sorted(words, key=lambda x: ''.join(sorted(x)))

        # Create a dictionary to store the parent of each word
        parent = {}
        for i, word in enumerate(sorted_words):
            parent[word] = word

        # Union-find algorithm to connect words
        def union(word1, word2):
            root1 = find(word1)
            root2 = find(word2)
            if root1 != root2:
                parent[root2] = root1

        def find(word):
            while parent[word] != word:
                parent[word] = parent[parent[word]]
                word = parent[word]
            return word

        # Group words using the union-find algorithm
        for i, word in enumerate(sorted_words):
            for j in range(len(word)):
                new_word = word[:j] + word[j+1:]
                if new_word in parent:
                    union(word, new_word)
                new_word = word[:j] + chr(ord(word[j])+1) + word[j+1:]
                if new_word in parent:
                    union(word, new_word)
                new_word = word[:j] + chr(ord(word[j])-1) + word[j+1:]
                if new_word in parent:
                    union(word, new_word)

        # Count the number of connected components and find the largest one
        count = collections.defaultdict(int)
        for word in parent.values():
            count[find(word)] += 1

        max_count = max(count.values())
        return [len(count), max_count]

class Solution:
    def validUtf8(self, data: List[int]) -> bool:
        i = 0
        while i < len(data):
            if data[i] & 0b10000000 == 0b10000000:
                i += 1
            elif data[i] & 0b11000000 == 0b11000000:
                j = i + 1
                while j < len(data) and data[j] & 0b10000000 == 0b10000000:
                    j += 1
                if j >= len(data):
                    return False
                i = j
            else:
                return False
        return True

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or not s:
            return ""

        dict_t = {}
        for char in t:
            dict_t[char] = dict_t.get(char, 0) + 1

        required = len(dict_t)
        formed = 0
        left = 0
        right = 0
        ans = float("inf"), None, None

        while right < len(s):
            character = s[right]
            dict_t[character] = dict_t.get(character, 0) - 1
            if dict_t[character] == 0:
                formed += 1

            while left <= right and formed == required:
                character = s[left]

                if right - left + 1 < ans[0]:
                    ans = (right - left + 1, left, right)

                dict_t[character] += 1
                if dict_t[character] > 0:
                    formed -= 1

            right += 1

        return "" if ans[0] == float("inf") else s[ans[1] : ans[2] + 1]

