class Solution:
    def distinctNames(self, ideas: List[str]) -> int:
        # Group ideas by their first letter
        first_letter_map = {}
        for idea in ideas:
            first_letter = idea[0]
            if first_letter not in first_letter_map:
                first_letter_map[first_letter] = set()
            first_letter_map[first_letter].add(idea[1:])

        total_valid_names = 0

        # Compare each pair of first letters
        for letter1 in first_letter_map:
            for letter2 in first_letter_map:
                if letter1 == letter2:
                    continue

                suffixes1 = first_letter_map[letter1]
                suffixes2 = first_letter_map[letter2]

                # Count the number of valid swaps
                common_suffixes = suffixes1 & suffixes2
                unique_to_1 = len(suffixes1) - len(common_suffixes)
                unique_to_2 = len(suffixes2) - len(common_suffixes)

                total_valid_names += unique_to_1 * unique_to_2

        return total_valid_names

# Definition for a binary tree node.
