#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            return TreeNode(val, root)

        queue = deque([root])
        level = 1

        while queue and level < depth - 1:
            size = len(queue)
            for _ in range(size):
                node = queue.popleft()
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            level += 1

        for node in queue:
            left_child = node.left
            right_child = node.right

            node.left = TreeNode(val)
            node.left.left = left_child

            node.right = TreeNode(val)
            node.right.right = right_child

        return root

class Solution:
    def smallestNumber(self, pattern: str) -> str:
        n = len(pattern)
        num = [str(i) for i in range(1, n + 2)]
        i = 0
        while i < n:
            if pattern[i] == 'D':
                j = i
                while j < n and pattern[j] == 'D':
                    j += 1
                num[i:j+1] = reversed(num[i:j+1])
                i = j
            else:
                i += 1
        return ''.join(num)

class Solution:
    def findPattern(self, board: List[List[int]], pattern: List[str]) -> List[int]:
        n = len(board)
        m = len(pattern)

        # Check if the pattern matches the entire board
        for i in range(n):
            for j in range(m):
                if board[i][j] != pattern[i][j]:
                    return [-1, -1]

        # Iterate over all possible positions in the board
        for i in range(n - m + 1):
            for j in range(m - m + 1):
                # Check if the pattern matches the current submatrix
                if board[i:i+m][j:j+m] == pattern:
                    return [i, j]

        return [-1, -1]

from typing import List

class Solution:
    def wordSquares(self, words: List[str]) -> List[List[str]]:
        self.words = words
        self.N = len(words[0])
        self.trie = {}
        self.buildTrie()
        self.results = []
        self.backtrack([])
        return self.results

    def buildTrie(self):
        for word in self.words:
            node = self.trie
            for char in word:
                if char not in node:
                    node[char] = {}
                node = node[char]
            node['#'] = word  # Mark the end of a word

    def backtrack(self, path):
        if len(path) == self.N:
            self.results.append(list(path))
            return

        row = len(path)
        prefix = ''.join([word[row] for word in path])
        candidates = self.getWordsWithPrefix(prefix)

        for candidate in candidates:
            path.append(candidate)
            self.backtrack(path)
            path.pop()

    def getWordsWithPrefix(self, prefix):
        node = self.trie
        for char in prefix:
            if char not in node:
                return []
            node = node[char]
        return [node['#']] if '#' in node else []

class Solution:
    def minElements(self, nums: List[int], limit: int, goal: int) -> int:
