class Solution:
    def numWays(self, words: List[str], target: str) -> int:
        MOD = 10**9 + 7

        # Count the frequency of each character at each position
        char_count = [collections.defaultdict(int) for _ in range(len(words[0]))]
        for word in words:
            for i, c in enumerate(word):
                char_count[i][c] += 1

        # Initialize the DP table
        dp = [[0] * (len(target) + 1) for _ in range(len(words[0]) + 1)]
        dp[0][0] = 1  # Base case: 1 way to form an empty target with an empty word

        # Fill the DP table
        for i in range(1, len(words[0]) + 1):
            for j in range(1, len(target) + 1):
                dp[i][j] = dp[i-1][j]  # Not using the current character
                if char_count[i-1][target[j-1]]:
                    dp[i][j] += dp[i-1][j-1] * char_count[i-1][target[j-1]]
                    dp[i][j] %= MOD

        return dp[-1][-1]

class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        return len(set(nums)) == len(nums) // 2

class Solution:
    def slidingPuzzle(self, board: List[List[int]]) -> int:
        target = "123450"
        start = ""
        for row in board:
            for num in row:
                start += str(num)
        visited = set()
        queue = deque([(start, start.index('0'), 0)])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            current, index, steps = queue.popleft()
            if current == target:
                return steps

            for dx, dy in directions:
                new_index = index + dx * 3 + dy
                if 0 <= new_index < 6:
                    new_board = list(current)
                    new_board[index], new_board[new_index] = new_board[new_index], new_board[index]
                    new_board_str = ''.join(new_board)

                    if new_board_str not in visited:
                        visited.add(new_board_str)
                        queue.append((new_board_str, new_index, steps + 1))

        return -1

from collections import Counter

class Solution:
    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:
        # Count the frequency of each barcode
        count = Counter(barcodes)
        # Sort barcodes by their frequency in descending order
        barcodes.sort(key=lambda x: -count[x])

        result = [None] * len(barcodes)
        odd_index = 0

        for barcode, freq in count.items():
            for _ in range(freq):
                result[odd_index] = barcode
                odd_index += 2
                if odd_index >= len(result):
                    odd_index = 1

        return result

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        @lru_cache(None)
        def dp(i, j):
            if i == j:
                return 0
            min_cost = float('inf')
            for mid in range(i, j):
                cost = dp(i, mid) + dp(mid+1, j) + sum(1 for c in s[i:mid+1] if c != s[mid])
                min_cost = min(min_cost, cost)
            return min_cost

        return dp(0, len(s)-1)

from typing import List
from collections import Counter

class Solution:
    def shareCandies(self, candies: List[int], k: int) -> int:
        if k == 0:
            return len(set(candies))

        total_candies = len(candies)
        unique_flavors = len(set(candies))

        if k >= total_candies:
            return 0

        # Count the frequency of each candy flavor
        candy_count = Counter(candies)

        max_unique = 0

        # Slide the window of size k over the candies array
        for i in range(total_candies - k + 1):
            # Remove the effect of the current window on unique flavors
            if candy_count[candies[i]] == 1:
                unique_flavors -= 1
            candy_count[candies[i]] -= 1

            # Add the effect of the current window on unique flavors
            if i + k < total_candies:
                if candy_count[candies[i + k]] == 0:
                    unique_flavors += 1
                candy_count[candies[i + k]] += 1

            # Update the maximum unique flavors found
            max_unique = max(max_unique, unique_flavors)

        return max_unique

class Solution:
    def maximumElementAfterDecrementingAndRearranging(self, arr: List[int]) -> int:
        # Sort the array
        arr.sort()

        # Find the index of the first element that is greater than 1
        i = 0
        while i < len(arr) and arr[i] <= 1:
            i += 1

        # If the first element is greater than 1, return the last element
        if i < len(arr):
            return arr[-1]

        # Otherwise, return the first element
        return arr[0]

class Solution:
    def numKLenSubstrNoRepeats(self, s: str, k: int) -> int:
        # Initialize the dictionary to keep track of character counts
        char_count = {}
        # Initialize the count of valid substrings
        count = 0

        # Iterate through the string with a sliding window
        for i in range(len(s)):
            # Increment the count of the current character
            char_count[s[i]] = char_count.get(s[i], 0) + 1

            # If the count exceeds k, remove the character from the left window
            while len(char_count) > k:
                char_count[s[i - k]] -= 1
                if char_count[s[i - k]] == 0:
                    del char_count[s[i - k]]

            # Update the count of valid substrings
            count += len(char_count) == k

        return count

class Solution:
    def smallestNumber(self, num: int) -> int:
        if num < 0:
            return int('-' + ''.join(sorted(str(-num), reverse=True)))
        else:
            return int(''.join(sorted(str(num))))

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        dirs = [(0,1),(1,0),(0,-1),(-1,0)]

        def isStable(row, col):
            stack = []
            for dx, dy in dirs:
                nx, ny = row + dx, col + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 1:
                    stack.append((nx, ny))
            return len(stack) == 0

        res = [0] * len(hits)

        for i, hit in enumerate(hits):
            row, col = hit
            if grid[row][col] == 1:
                if isStable(row-1, col):
                    res[i] += 1
                if isStable(row+1, col):
                    res[i] += 1
                if isStable(row, col-1):
                    res[i] += 1
                if isStable(row, col+1):
                    res[i] += 1

        return res

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        ans = 0

        # Check each row for magic squares
        for i in range(rows):
            row_sum = sum(grid[i])
            if row_sum % 3 != 0:
                continue

            # Check each column for magic squares
            for j in range(cols):
                col_sum = sum(grid[x][j] for x in range(rows))
                if col_sum % 3 != 0:
                    continue

                # Check the main diagonal for magic squares
                if grid[i][i] + grid[i][cols-1] + grid[i][rows-1] != row_sum:
                    continue

                # Check the anti-diagonal for magic squares
                if grid[i][i] - grid[i][cols-1] + grid[i][rows-1] != col_sum:
                    continue

                ans += 1

        return ans

from typing import List

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        word_set = set(words)

        def is_concatenated(word):
            for i in range(1, len(word)):
                prefix = word[:i]
                suffix = word[i:]
                if prefix in word_set and (suffix in word_set or is_concatenated(suffix)):
                    return True
            return False

        return [word for word in words if is_concatenated(word)]
